// Content with portions generated by generative AI platform
package org.eclipse.kura.net.admin.monitor;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

public class MonitorLoopTest {

    private static final int RUNS = 3;

    private int monitorRuns;
    private int waits;
    private Throwable monitorFailure;
    private Throwable propagatedThrowable;

    /*
     * Scenarios
     */

    @Test
    public void waitsBetweenSuccessfulRuns() {
        givenMonitorSucceeds();

        whenLoopRunsUntilStoppedAfter(RUNS);

        thenNothingPropagated();
        thenMonitorRanTimes(RUNS);
        thenLoopWaitedTimes(RUNS);
    }

    @Test
    public void waitsBetweenRunsWhenMonitorThrowsException() {
        givenMonitorFailsWith(new IllegalStateException("monitor failure"));

        whenLoopRunsUntilStoppedAfter(RUNS);

        thenNothingPropagated();
        thenMonitorRanTimes(RUNS);
        thenLoopWaitedTimes(RUNS);
    }

    @Test
    public void waitsBetweenRunsWhenMonitorFailsWithLinkageError() {
        givenMonitorFailsWith(new NoClassDefFoundError("missing class"));

        whenLoopRunsUntilStoppedAfter(RUNS);

        thenNothingPropagated();
        thenMonitorRanTimes(RUNS);
        thenLoopWaitedTimes(RUNS);
    }

    @Test
    public void stopsAndPropagatesVirtualMachineError() {
        givenMonitorFailsWith(new OutOfMemoryError("simulated"));

        whenLoopRunsUntilStoppedAfter(RUNS);

        thenPropagated(OutOfMemoryError.class);
        thenMonitorRanTimes(1);
        thenLoopWaitedTimes(0);
    }

    /*
     * Steps
     */

    private void givenMonitorSucceeds() {
        this.monitorFailure = null;
    }

    private void givenMonitorFailsWith(Throwable failure) {
        this.monitorFailure = failure;
    }

    private void whenLoopRunsUntilStoppedAfter(int runs) {
        try {
            MonitorLoop.run("test", () -> this.waits >= runs, this::monitor, () -> this.waits++);
        } catch (Throwable e) {
            this.propagatedThrowable = e;
        }
    }

    private void thenNothingPropagated() {
        assertNull(this.propagatedThrowable);
    }

    private void thenPropagated(Class<? extends Throwable> expected) {
        assertTrue("unexpected: " + this.propagatedThrowable, expected.isInstance(this.propagatedThrowable));
    }

    private void thenMonitorRanTimes(int expected) {
        assertEquals(expected, this.monitorRuns);
    }

    private void thenLoopWaitedTimes(int expected) {
        assertEquals(expected, this.waits);
    }

    /*
     * Utilities
     */

    private void monitor() {
        this.monitorRuns++;
        if (this.monitorFailure != null) {
            sneakyThrow(this.monitorFailure);
        }
    }

    @SuppressWarnings("unchecked")
    private static <E extends Throwable> void sneakyThrow(Throwable e) throws E {
        throw (E) e;
    }
}
